-- Independently authored synthetic schema-25 contract fixture. No original source SQL included.
CREATE TABLE agents(id TEXT PRIMARY KEY,name TEXT,system_prompt TEXT,model TEXT,avatar TEXT,theme TEXT,address TEXT,capabilities TEXT,created_at TEXT,working_dir TEXT);
CREATE TABLE sessions(id TEXT PRIMARY KEY,agent_id TEXT,title TEXT,created_at TEXT,updated_at TEXT);
CREATE TABLE messages(id TEXT PRIMARY KEY,session_id TEXT,seq INTEGER,role TEXT,content TEXT,reasoning TEXT,tool_calls TEXT,tool_call_id TEXT,created_at TEXT,parent_id TEXT,images TEXT,status TEXT);
CREATE UNIQUE INDEX sequence_contract ON messages(session_id,seq);
CREATE TABLE memory_episodes(id TEXT UNIQUE,agent_id TEXT,summary TEXT,salience REAL,embedding BLOB,created_at TEXT,session_id TEXT,valid_to TEXT,pinned INTEGER);
CREATE TABLE tasks(id TEXT PRIMARY KEY,agent_id TEXT,status TEXT,created_at TEXT,updated_at TEXT,trigger_kind TEXT,input TEXT,output TEXT,error TEXT,transcript TEXT);
CREATE TABLE tools(name TEXT PRIMARY KEY,description TEXT,parameters TEXT,source TEXT,enabled INTEGER,updated_at TEXT);
CREATE TABLE schedules(id TEXT PRIMARY KEY,agent_id TEXT,name TEXT,cron TEXT,payload TEXT,enabled INTEGER,last_run TEXT,next_run TEXT,created_at TEXT);
CREATE TABLE plugins(id TEXT PRIMARY KEY,name TEXT,version TEXT,manifest TEXT,enabled INTEGER,installed_at TEXT);
CREATE TABLE watch_triggers(id TEXT PRIMARY KEY,agent_id TEXT,name TEXT,path TEXT,recursive INTEGER,kind TEXT,enabled INTEGER,created_at TEXT);
CREATE TABLE skills(id TEXT PRIMARY KEY,name TEXT,description TEXT,instructions TEXT,category TEXT,enabled INTEGER,created_at TEXT);
CREATE TABLE methods(id TEXT PRIMARY KEY,name TEXT,description TEXT,instructions TEXT,enabled INTEGER,created_at TEXT);
CREATE TABLE tool_recipes(id TEXT PRIMARY KEY,name TEXT,description TEXT,command TEXT,parameters TEXT,enabled INTEGER,created_at TEXT);
CREATE TABLE agent_souls(agent_id TEXT PRIMARY KEY,content TEXT,updated_at TEXT);
CREATE TABLE interaction_signals(id TEXT PRIMARY KEY,session_id TEXT,message_id TEXT,agent_id TEXT,kind TEXT,payload TEXT,created_at TEXT);
CREATE TABLE agent_soul_candidates(agent_id TEXT PRIMARY KEY,content TEXT,eval_score REAL,base_champion_hash TEXT,created_at TEXT,content_hash TEXT);
CREATE TABLE mcp_providers(id TEXT PRIMARY KEY,name TEXT,transport TEXT,enabled INTEGER);
CREATE TABLE lessons(id TEXT UNIQUE,agent_id TEXT,polarity TEXT,trigger TEXT,root_cause TEXT,corrected_behavior TEXT,scope TEXT,source_session_id TEXT,embedding BLOB,usage_count INTEGER,success_count INTEGER,valid_to TEXT,created_at TEXT);
CREATE TABLE artifacts(id TEXT UNIQUE,kind TEXT,session_id TEXT,message_id TEXT,agent_id TEXT,mime TEXT,title TEXT,relpath TEXT,size INTEGER,created_at TEXT,store_id TEXT,source_mtime INTEGER);
CREATE TABLE artifact_stores(id TEXT UNIQUE,label TEXT,root_path TEXT,managed INTEGER,created_at TEXT,deep_index INTEGER);
CREATE TABLE artifact_index(artifact_id TEXT UNIQUE,text TEXT,embedding BLOB,updated_at TEXT);
CREATE VIRTUAL TABLE memory_fts USING fts5(summary,content=memory_episodes,content_rowid=rowid,tokenize='porter unicode61');
CREATE VIRTUAL TABLE lessons_fts USING fts5(trigger,content=lessons,content_rowid=rowid,tokenize='porter unicode61');
CREATE VIRTUAL TABLE artifact_index_fts USING fts5(text,content=artifact_index,content_rowid=rowid,tokenize='porter unicode61');
CREATE TRIGGER synthetic_memory_insert AFTER INSERT ON memory_episodes BEGIN INSERT INTO memory_fts(rowid,summary) VALUES(new.rowid,new.summary); END;
CREATE TRIGGER synthetic_lesson_insert AFTER INSERT ON lessons BEGIN INSERT INTO lessons_fts(rowid,trigger) VALUES(new.rowid,new.trigger); END;
CREATE TRIGGER synthetic_artifact_insert AFTER INSERT ON artifact_index BEGIN INSERT INTO artifact_index_fts(rowid,text) VALUES(new.rowid,new.text); END;
-- Also preserve extensions that do not change user_version, including WITHOUT ROWID.
CREATE TABLE extension_payload(key TEXT PRIMARY KEY,payload BLOB) WITHOUT ROWID;
CREATE VIEW synthetic_view AS SELECT content,status FROM messages;
